package dev.pedro.learning.ecommerce.notification.application;import dev.pedro.learning.ecommerce.notification.domain.*;import dev.pedro.learning.ecommerce.notification.event.*;import dev.pedro.learning.ecommerce.notification.inbox.*;import jakarta.enterprise.context.ApplicationScoped;import jakarta.transaction.Transactional;import org.jboss.logging.Logger;import org.jboss.logging.MDC;import java.time.Instant;import java.util.UUID;@ApplicationScoped public class NotificationSagaService{private static final Logger LOG=Logger.getLogger(NotificationSagaService.class);private final NotificationRepository notifications;private final InboxEventRepository inbox;private final NotificationDeliveryService delivery;public NotificationSagaService(NotificationRepository notifications,InboxEventRepository inbox,NotificationDeliveryService delivery){this.notifications=notifications;this.inbox=inbox;this.delivery=delivery;}@Transactional public void onOrderConfirmed(EventEnvelope<OrderConfirmedPayload> event){MDC.put("correlationId",event.correlationId().toString());try{if(inbox.findById(event.eventId())!=null){LOG.info("[NOTIFICATION] Duplicate OrderConfirmed ignored");return;}InboxEvent row=new InboxEvent();row.eventId=event.eventId();row.eventType=event.eventType();row.receivedAt=Instant.now();inbox.persist(row);NotificationEntity existing=notifications.findByOrderId(event.payload().orderId());if(existing!=null){row.processedAt=Instant.now();return;}delivery.deliver(event.eventId(),event.payload().orderId(),event.payload().customerEmail());NotificationEntity n=new NotificationEntity();n.id=UUID.randomUUID();n.orderId=event.payload().orderId();n.email=event.payload().customerEmail();n.attempts=delivery.attempts(event.eventId());n.sentAt=Instant.now();notifications.persist(n);row.processedAt=Instant.now();LOG.infof("[NOTIFICATION] EmailSent after %d attempt(s)",n.attempts);delivery.clear(event.eventId());}finally{MDC.remove("correlationId");}}}